import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import crypto from "node:crypto";
import http from "node:http";
import https from "node:https";
import { execFileSync } from "node:child_process";
import { createRequire } from "node:module";

// Live integration test: only creates and removes fixtures generated by this run.
if (process.env.RUN_FIREBASE_LIVE_TESTS !== "1") {
  throw new Error(
    "Defina RUN_FIREBASE_LIVE_TESTS=1 para autorizar as contas e os dados temporários deste teste.",
  );
}
const project = process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID;
const apiKey = process.env.NEXT_PUBLIC_FIREBASE_API_KEY;
if (!project || !apiKey)
  throw new Error("Configuração pública do Firebase ausente.");
const origin = process.env.FIREBASE_TEST_APP_ORIGIN ?? "http://localhost:3001";
const runId = crypto.randomBytes(8).toString("hex");
const root = `projects/${project}/databases/(default)/documents`;
const firestore = `https://firestore.googleapis.com/v1/${root}`;
const fixtures = [];
const results = [];
const cleanup = [];
const text = (stringValue) => ({ stringValue });
const timestamp = { timestampValue: new Date().toISOString() };
let adminToken;

async function request(
  url,
  { token, method = "GET", body, headers = {} } = {},
) {
  // Node fetch ignores a custom Host header. Use the HTTP client for virtual-host checks.
  if (headers.Host) {
    const transport = new URL(url).protocol === "https:" ? https : http;
    return new Promise((resolve, reject) => {
      const req = transport.request(
        url,
        {
          method,
          headers: {
            ...(body ? { "Content-Type": "application/json" } : {}),
            ...headers,
          },
          signal: AbortSignal.timeout(20000),
        },
        (response) => {
          const chunks = [];
          response.on("data", (chunk) => chunks.push(chunk));
          response.on("error", reject);
          response.on("end", () =>
            resolve(
              new Response(Buffer.concat(chunks), {
                status: response.statusCode,
                headers: response.headers,
              }),
            ),
          );
        },
      );
      req.on("error", reject);
      req.end(body ? JSON.stringify(body) : undefined);
    });
  }
  return fetch(url, {
    method,
    redirect: "manual",
    signal: AbortSignal.timeout(20000),
    headers: {
      ...(body ? { "Content-Type": "application/json" } : {}),
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...headers,
    },
    ...(body ? { body: JSON.stringify(body) } : {}),
  });
}
function check(name, actual, expected) {
  const passed = Array.isArray(expected)
    ? expected.includes(actual)
    : actual === expected;
  results.push({ name, passed, actual, expected });
  console.log(`${passed ? "PASS" : "FAIL"}: ${name} (${actual})`);
}
async function requireOk(response, label) {
  if (!response.ok) throw new Error(`${label}: HTTP ${response.status}`);
  return response.json();
}
async function commit(writes, token) {
  return request(`${firestore}:commit`, {
    method: "POST",
    token,
    body: { writes },
  });
}
function createWrite(relative, fields) {
  return {
    update: { name: `${root}/${relative}`, fields },
    currentDocument: { exists: false },
    updateTransforms: [
      { fieldPath: "createdAt", setToServerValue: "REQUEST_TIME" },
    ],
  };
}
function updateWrite(relative, fields) {
  return {
    update: { name: `${root}/${relative}`, fields },
    updateMask: { fieldPaths: Object.keys(fields) },
    currentDocument: { exists: true },
    updateTransforms: [
      { fieldPath: "updatedAt", setToServerValue: "REQUEST_TIME" },
    ],
  };
}
async function getAdminToken() {
  const configFile =
    process.env.FIREBASE_CLI_CONFIG ??
    path.join(os.homedir(), ".config/configstore/firebase-tools.json");
  const config = JSON.parse(fs.readFileSync(configFile, "utf8"));
  const cli = fs.realpathSync(
    execFileSync("which", ["firebase"], { encoding: "utf8" }).trim(),
  );
  const require = createRequire(import.meta.url);
  const api = require(path.resolve(path.dirname(cli), "../api.js"));
  const response = await request("https://oauth2.googleapis.com/token", {
    method: "POST",
    body: {
      client_id: api.clientId(),
      client_secret: api.clientSecret(),
      refresh_token: config.tokens.refresh_token,
      grant_type: "refresh_token",
    },
  });
  return (await requireOk(response, "Autenticação administrativa para limpeza"))
    .access_token;
}

try {
  adminToken = await getAdminToken();
  const permission = await requireOk(
    await request(
      `https://cloudresourcemanager.googleapis.com/v1/projects/${project}:testIamPermissions`,
      {
        method: "POST",
        token: adminToken,
        body: { permissions: ["datastore.entities.delete"] },
      },
    ),
    "Permissão de limpeza",
  );
  if (!permission.permissions?.includes("datastore.entities.delete"))
    throw new Error(
      "Sem permissão para limpar os dados temporários; teste cancelado antes de criar contas.",
    );
  const release = await requireOk(
    await request(
      `https://firebaserules.googleapis.com/v1/projects/${project}/releases/cloud.firestore`,
      { token: adminToken },
    ),
    "Regras publicadas",
  );
  const rules = await requireOk(
    await request(
      `https://firebaserules.googleapis.com/v1/${release.rulesetName}`,
      { token: adminToken },
    ),
    "Conteúdo das regras",
  );
  check(
    "regras publicadas iguais ao arquivo local",
    rules.source.files.some(
      (file) => file.content === fs.readFileSync("firestore.rules", "utf8"),
    ),
    true,
  );

  for (const label of ["a", "b"]) {
    const email = `security-test-${runId}-${label}@example.com`;
    const password = `T3st!${crypto.randomBytes(24).toString("hex")}`;
    const signup = await requireOk(
      await request(
        `https://identitytoolkit.googleapis.com/v1/accounts:signUp?key=${apiKey}`,
        { method: "POST", body: { email, password, returnSecureToken: true } },
      ),
      `Criar conta temporária ${label}`,
    );
    const fixture = {
      label,
      uid: signup.localId,
      token: signup.idToken,
      slug: `teste-${runId}-${label}`,
      paths: [],
    };
    fixtures.push(fixture);
    fixture.paths.push(`tenants/${fixture.uid}`);
    await requireOk(
      await commit(
        [
          createWrite(`tenants/${fixture.uid}`, {
            ownerUid: text(fixture.uid),
            ownerName: text("Responsável de teste"),
            name: text(`Restaurante temporário ${label}`),
            status: text("pending"),
          }),
        ],
        fixture.token,
      ),
      `Cadastro inicial ${label}`,
    );
    fixture.paths.push(`tenantDomains/${fixture.slug}`);
    await requireOk(
      await commit(
        [
          createWrite(`tenantDomains/${fixture.slug}`, {
            tenantId: text(fixture.uid),
          }),
          updateWrite(`tenants/${fixture.uid}`, { slug: text(fixture.slug) }),
        ],
        fixture.token,
      ),
      `Reserva de domínio ${label}`,
    );
    check(`cadastro inicial e reserva de domínio ${label}`, true, true);
    const login = await requireOk(
      await request(
        `https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=${apiKey}`,
        { method: "POST", body: { email, password, returnSecureToken: true } },
      ),
      `Login ${label}`,
    );
    fixture.token = login.idToken;
    check(`login real da conta ${label}`, login.localId === fixture.uid, true);
    const wrong = await request(
      `https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=${apiKey}`,
      {
        method: "POST",
        body: {
          email,
          password: "SenhaIncorreta!123",
          returnSecureToken: true,
        },
      },
    );
    check(`senha incorreta bloqueada ${label}`, wrong.status, 400);
    const session = await request(`${origin}/api/auth/session`, {
      method: "POST",
      headers: { Origin: origin },
      body: { idToken: fixture.token },
    });
    check(`sessão do cadastro pendente ${label}`, session.status, 200);
    const cookie = session.headers.get("set-cookie") ?? "";
    check(`cookie HttpOnly ${label}`, cookie.includes("HttpOnly"), true);
    check(
      `cookie SameSite Strict ${label}`,
      cookie.toLowerCase().includes("samesite=strict"),
      true,
    );
    check(
      `dashboard próprio ${label}`,
      (
        await request(`${origin}/dashboard`, {
          headers: { Cookie: `cardap_session=${fixture.token}` },
        })
      ).status,
      200,
    );
  }
  for (const own of fixtures) {
    // Seed only this run's fixtures through IAM; ALL authorization checks below use user tokens.
    const productPath = `tenants/${own.uid}/products/security-product`;
    const categoryPath = `tenants/${own.uid}/categories/security-category`;
    own.paths.push(productPath, categoryPath);
    await requireOk(
      await commit(
        [
          updateWrite(`tenants/${own.uid}`, {
            status: text("configured"),
            asaasWalletId: text("test_wallet_not_for_payments"),
          }),
          createWrite(categoryPath, {
            storeId: text(own.uid),
            name: text("Categoria de teste"),
          }),
          createWrite(productPath, {
            storeId: text(own.uid),
            name: text("Produto de teste"),
            description: text("Fixture temporária"),
            categoryId: text("security-category"),
            priceCents: { integerValue: "1000" },
            available: { booleanValue: true },
            imagePath: text(
              `tenants/${own.uid}/products/security-product/image`,
            ),
            updatedAt: timestamp,
          }),
        ],
        adminToken,
      ),
      `Preparar fixtures operacionais ${own.label}`,
    );
  }
  for (const own of fixtures) {
    const other = fixtures.find((item) => item !== own);
    const product = `tenants/${own.uid}/products/security-product`;
    const foreignProduct = `tenants/${other.uid}/products/security-product`;
    for (const [label, relative, expected] of [
      ["leitura do próprio tenant", `tenants/${own.uid}`, 200],
      ["leitura do próprio produto", product, 200],
      ["leitura do tenant alheio", `tenants/${other.uid}`, 403],
      ["leitura do produto alheio", foreignProduct, 403],
      [
        "leitura da categoria alheia",
        `tenants/${other.uid}/categories/security-category`,
        403,
      ],
      ["listagem global de tenants", "tenants?pageSize=10", 403],
      [
        "listagem dos próprios produtos",
        `tenants/${own.uid}/products?pageSize=10`,
        200,
      ],
      [
        "listagem dos produtos alheios",
        `tenants/${other.uid}/products?pageSize=10`,
        403,
      ],
    ])
      check(
        `${own.label}: ${label}`,
        (await request(`${firestore}/${relative}`, { token: own.token }))
          .status,
        expected,
      );
    check(
      `${own.label}: edição do próprio produto`,
      (
        await commit(
          [updateWrite(product, { name: text("Produto atualizado") })],
          own.token,
        )
      ).status,
      200,
    );
    check(
      `${own.label}: edição do produto alheio`,
      (
        await commit(
          [updateWrite(foreignProduct, { name: text("Tentativa indevida") })],
          own.token,
        )
      ).status,
      403,
    );
    check(
      `${own.label}: exclusão do produto alheio`,
      (await commit([{ delete: `${root}/${foreignProduct}` }], own.token))
        .status,
      403,
    );
    check(
      `${own.label}: troca do proprietário`,
      (
        await commit(
          [updateWrite(`tenants/${own.uid}`, { ownerUid: text(other.uid) })],
          own.token,
        )
      ).status,
      403,
    );
    check(
      `${own.label}: ativação indevida da loja`,
      (
        await commit(
          [updateWrite(`tenants/${own.uid}`, { status: text("active") })],
          own.token,
        )
      ).status,
      403,
    );
    check(
      `${own.label}: apropriação do domínio alheio`,
      (
        await commit(
          [
            updateWrite(`tenantDomains/${other.slug}`, {
              tenantId: text(own.uid),
            }),
          ],
          own.token,
        )
      ).status,
      403,
    );
    const ownHost = `${own.slug}.localhost:${new URL(origin).port || "80"}`;
    check(
      `${own.label}: dashboard no domínio próprio`,
      (
        await request(`${origin}/dashboard`, {
          headers: { Host: ownHost, Cookie: `cardap_session=${own.token}` },
        })
      ).status,
      200,
    );
    const host = `${other.slug}.localhost:${new URL(origin).port || "80"}`;
    check(
      `${own.label}: dashboard de outro domínio`,
      (
        await request(`${origin}/dashboard`, {
          headers: { Host: host, Cookie: `cardap_session=${own.token}` },
        })
      ).status,
      403,
    );
    check(
      `${own.label}: sessão em outro domínio`,
      (
        await request(`${origin}/api/auth/session`, {
          method: "POST",
          headers: { Host: host, Origin: `http://${host}` },
          body: { idToken: own.token },
        })
      ).status,
      403,
    );
    check(
      `${own.label}: URL interna direta`,
      (
        await request(`${origin}/tenants/${own.slug}/dashboard`, {
          headers: { Cookie: `cardap_session=${own.token}` },
        })
      ).status,
      404,
    );
    const logout = await request(`${origin}/api/auth/session`, {
      method: "DELETE",
      headers: { Origin: origin },
    });
    check(
      `${own.label}: logout remove cookie`,
      logout.status === 204 &&
        (logout.headers.get("set-cookie") ?? "").includes("Max-Age=0"),
      true,
    );
  }
  check(
    "anônimo: leitura do tenant bloqueada",
    (await request(`${firestore}/tenants/${fixtures[0].uid}`)).status,
    403,
  );
  check(
    "anônimo: dashboard bloqueado",
    (await request(`${origin}/dashboard`)).status,
    307,
  );
  check(
    "CSRF: origem externa bloqueada",
    (
      await request(`${origin}/api/auth/session`, {
        method: "POST",
        headers: { Origin: "https://external.example" },
        body: { idToken: fixtures[0].token },
      })
    ).status,
    403,
  );
} catch (error) {
  results.push({ name: "execução", passed: false, error: error.message });
  console.error(error.message);
} finally {
  for (const fixture of fixtures.reverse()) {
    for (const relative of fixture.paths.reverse()) {
      try {
        const response = await request(`${firestore}/${relative}`, {
          method: "DELETE",
          token: adminToken,
        });
        cleanup.push({
          resource: relative,
          removed: response.ok || response.status === 404,
        });
      } catch {
        cleanup.push({ resource: relative, removed: false });
      }
    }
    try {
      const response = await request(
        `https://identitytoolkit.googleapis.com/v1/accounts:delete?key=${apiKey}`,
        { method: "POST", body: { idToken: fixture.token } },
      );
      cleanup.push({ resource: `auth/${fixture.uid}`, removed: response.ok });
    } catch {
      cleanup.push({ resource: `auth/${fixture.uid}`, removed: false });
    }
  }
  const report = {
    executedAt: new Date().toISOString(),
    project,
    appOrigin: origin,
    runId,
    passed: results.filter((item) => item.passed).length,
    failed: results.filter((item) => !item.passed).length,
    results,
    cleanup,
  };
  fs.mkdirSync("test-results", { recursive: true });
  fs.writeFileSync(
    "test-results/firebase-live-isolation.json",
    JSON.stringify(report, null, 2),
  );
  console.log(
    JSON.stringify({
      passed: report.passed,
      failed: report.failed,
      cleanupComplete: cleanup.every((item) => item.removed),
      temporaryAccounts: fixtures.length,
    }),
  );
  if (report.failed || cleanup.some((item) => !item.removed))
    process.exitCode = 1;
}
